module ip_checksum #(parameter WIDTH = 16, parameter NUM_WORDS = 5) (  
    input wire clk,  
    input wire rst,  
    input wire [WIDTH-1:0] data_in,  
    input wire valid_in,  
    output reg [WIDTH-1:0] checksum_out,  
    output reg done  
);  
    reg [WIDTH-1:0] sum;  
    integer count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            sum <= 0;  
            count <= 0;  
            checksum_out <= 0;  
            done <= 0;  
        end else if (valid_in && count < NUM_WORDS) begin  
            sum <= sum + data_in;  
            count <= count + 1;  
            if (count == NUM_WORDS - 1) begin  
                checksum_out <= ~sum;  
                done <= 1;  
            end  
        end  
    end  
endmodule

