    parameter c0 = 4'd1;
    parameter c1 = 4'd2;
    parameter c2 = 4'd3;
    parameter c3 = 4'd4;

    // FIR filter operation
    assign y = (c0 * x0) + (c1 * x1) + (c2 * x2) + (c3 * x3);
endmodule

