module deserializer (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [31:0] data_in,
    output reg serial_out
);
    reg [4:0] bit_index; // 0 to 31

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_index <= 0;
            serial_out <= 0;
        end else if (enable) begin
            serial_out <= data_in[bit_index];
            if (bit_index < 31)
                bit_index <= bit_index + 1;
            else
                bit_index <= 0; // Reset to start over
        end
    end
endmodule

