module serializer (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [31:0] parallel_in,
    output reg serial_out
);
    reg [31:0] shift_reg;
    reg [4:0] count; // 5 bits to count from 0 to 31

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 32'b0;
            count <= 5'b0;
            serial_out <= 1'b0;
        end else if (start) begin
            shift_reg <= parallel_in;
            count <= 5'b0;
        end else if (count < 32) begin
            serial_out <= shift_reg[31];
            shift_reg <= {shift_reg[30:0], 1'b0}; // Shift left
            count <= count + 1;
        end
    end
endmodule

