module sipo_shift_register (  
    input clk,  
    input reset,  
    input load,  
    input data_in,  
    output reg [7:0] data_out  
);  
    reg [7:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 8'b0;  
        end else if (load) begin  
            shift_reg <= {shift_reg[6:0], data_in};  
        end  
    end  

    always @(*) begin  
        data_out = shift_reg;  
