module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire activity,  
    output reg system_reset  
);  
    reg [3:0] counter;  // 4-bit counter for timing  
    parameter THRESHOLD = 4'b1111; // Threshold for reset  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 4'b0000;  
            system_reset <= 1'b0;  
        end else if (activity) begin  
            counter <= 4'b0000;  
            system_reset <= 1'b0;  
        end else begin  
            if (counter < THRESHOLD)  
                counter <= counter + 1;  
            if (counter == THRESHOLD)  
                system_reset <= 1'b1;  
        end  
    end  
endmodule

