    reg [3:0] size;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            size <= 0;
            valid <= 0;
        end else begin
            if (insert_req && size < 16) begin
                heap[size] <= insert_val;
                size <= size + 1;
                // Perform up-heap operation
                // (Add logic to maintain the heap property)
            end

            if (extract_req && size > 0) begin
                min_val <= heap[0]; // Root is the minimum value
                valid <= 1;
                heap[0] <= heap[size - 1]; // Move last element to root
                size <= size - 1;
                // Perform down-heap operation
                // (Add logic to maintain the heap property)
            end else begin
                valid <= 0;
            end
        end
    end
endmodule

