    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 4'b1111) begin // Toggle output every 16 clock cycles
                out <= ~out;
            end
        end
    end
endmodule

