            count <= 0;
            encoding <= 0;
        end else if (data_valid) begin
            if (!encoding) begin
                current_value <= data_in;
                count <= 1;
                encoding <= 1;
            end else if (data_in == current_value) begin
                count <= count + 1;
            end else begin
                rle_value <= current_value;
                rle_count <= count;
                rle_ready <= 1;
                current_value <= data_in;
                count <= 1;
            end
        end else if (encoding) begin
            rle_value <= current_value;
            rle_count <= count;
            rle_ready <= 1;
            encoding <= 0;
        end
    end
endmodule

