module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    output reg watchdog_reset  
);  
    parameter TIMEOUT = 5; // Number of clock cycles before reset  
    reg [2:0] count; // 3-bit counter to count clock cycles  

    always @(posedge clk or negedge reset) begin  
        if (!reset) begin  
            count <= 0;  
            watchdog_reset <= 0;  
        end else begin  
            if (count < TIMEOUT) begin  
                count <= count + 1;  
                watchdog_reset <= 0;  
            end else begin  
                watchdog_reset <= 1;  
            end  
        end  
    end  
endmodule

