module i2c_master (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg scl,
    output reg sda,
    output reg done,
    output reg [7:0] data_out
);
    reg [3:0] state;
    reg [3:0] bit_cnt;
    parameter IDLE = 4'd0, START = 4'd1, SEND = 4'd2, RECV = 4'd3, STOP = 4'd4;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            scl <= 1;
            sda <= 1;
            done <= 0;
            data_out <= 8'b0;
            bit_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                        done <= 0;
                    end
                end

                START: begin
                    sda <= 0;  // Start condition
                    state <= SEND;
                    bit_cnt <= 0;
                    scl <= 0; 
                end

                SEND: begin
                    if (bit_cnt < 8) begin
                        scl <= 1;
                        sda <= data_in[7 - bit_cnt]; // Send MSB first
                        bit_cnt <= bit_cnt + 1;
                        state <= (bit_cnt == 7) ? RECV : SEND;
                    end
                end

                RECV: begin
                    scl <= 1;
                    sda <= 1; // Release SDA for slave to send data
                    data_out[7 - bit_cnt] <= sda; // Read data from slave
                    bit_cnt <= bit_cnt + 1;
                    if (bit_cnt == 8) begin
                        state <= STOP;
                    end
                end

                STOP: begin
                    scl <= 1;
                    sda <= 0;  // Prepare for stop condition
                    sda <= 1;  // Stop condition
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

