module RRT (
    input clk,
    input rst,
    input [4:0] start_point,
    input [4:0] goal_point,
    output reg [4:0] path_length,
    output reg success
);

    reg [4:0] path_memory [0:15]; // Memory to store the path
    reg [3:0] path_index; // Index for path memory
    reg [4:0] current_position;

    initial begin
        path_index = 0;
        path_length = 0;
        success = 0;
        current_position = start_point;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            path_index <= 0;
            path_length <= 0;
            success <= 0;
            current_position <= start_point;
        end else if (path_index < 16) begin
            // Randomly sample new point and store in path_memory
            // For simulation, just move towards the goal
            if (current_position < goal_point) begin
                current_position <= current_position + 1; // Move right
            end else if (current_position > goal_point) begin
                current_position <= current_position - 1; // Move left
            end

            path_memory[path_index] <= current_position;
            path_index <= path_index + 1;
            path_length <= path_index + 1; // Update path length

            if (current_position == goal_point) begin
                success <= 1; // Goal reached
            end
        end
    end
endmodule

