module uart_transmitter #(parameter baud_rate = 9600, parameter clk_freq = 50000000) (  
    input wire clk,  
    input wire reset,  
    input wire start_transmit,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  

    localparam BIT_TIME = clk_freq / baud_rate;  
    localparam IDLE = 2'b00, START = 2'b01, DATA = 2'b10, STOP = 2'b11;  
    reg [1:0] state, next_state;  
    reg [3:0] bit_cnt;  
    reg [15:0] clk_div;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            busy <= 0;  
            clk_div <= 0;  
            tx <= 1;  
        end else begin  
            state <= next_state;  
            if (state == DATA) begin  
                clk_div <= clk_div + 1;  
                if (clk_div == BIT_TIME) begin  
                    clk_div <= 0;  
                    bit_cnt <= bit_cnt + 1;  
                end  
            end  
        end  
    end  

    always @* begin  
        next_state = state;  
        case (state)  
            IDLE: begin  
                tx = 1;  
                busy = 0;  
                if (start_transmit) begin  
                    next_state = START;  
                    busy = 1;  
                    bit_cnt = 0;  
                    clk_div = 0;  
                end  
            end  
            START: begin  
                tx = 0;  
                if (clk_div == BIT_TIME - 1) begin  
                    next_state = DATA;  
                    clk_div = 0;  
                end  
            end  
            DATA: begin  
                if (clk_div == BIT_TIME - 1) begin  
                    tx = data_in[bit_cnt];  
                    if (bit_cnt == 7)  
                        next_state = STOP;  
                end  
            end  
            STOP: begin  
                if (clk_div == BIT_TIME - 1) begin  
                    tx = 1;  
                    next_state = IDLE;  
                    busy = 0;  
                end  
            end  
        endcase  
    end  
endmodule

