module restoring_divider(clk, start, numerator, denominator, quotient, remainder, done);  
    input clk;  
    input start;  
    input [3:0] numerator;  
    input [1:0] denominator;  
    output reg [3:0] quotient;  
    output reg [3:0] remainder;  
    output reg done;  

    reg [3:0] A;  // Accumulator  
    reg [1:0] B;  // Divisor  
    reg [2:0] count;  

    always @(posedge clk) begin  
        if (start) begin  
            A <= numerator;  
            B <= denominator;  
            quotient <= 4'b0;  
            remainder <= 4'b0;  
            count <= 3'b100; // 4 bits to divide  
            done <= 0;  
        end else if (count > 0) begin  
            A <= {A[2:0], 1'b0}; // Shift left  
            quotient <= {quotient[2:0], 1'b0};  
            if (A >= B) begin  
                A <= A - B;  
                quotient[0] <= 1;  
            end  
            count <= count - 1;  
            if (count == 1) begin  
                remainder <= A;  
                done <= 1;  
            end  
        end  
    end  
endmodule

