module viterbi_decoder(clk, rst, input_bit, output_bit);  
    input clk;  
    input rst;  
    input input_bit;  
    output reg [1:0] output_bit;  

    reg [2:0] state;  
    reg [2:0] next_state;  

    // State encoding  
    localparam S0 = 3'd0;  
    localparam S1 = 3'd1;  
    localparam S2 = 3'd2;  
    localparam S3 = 3'd3;  

    always @(posedge clk or posedge rst) begin  
        if (rst)  
            state <= S0;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            S0: begin  
                if (input_bit) begin  
                    next_state = S1;  
                    output_bit = 2'b00;  
                end else begin  
                    next_state = S2;  
                    output_bit = 2'b11;  
                end  
            end  
            S1: begin  
                if (input_bit) begin  
                    next_state = S0;  
                    output_bit = 2'b01;  
                end else begin  
                    next_state = S3;  
                    output_bit = 2'b10;  
                end  
            end  
            S2: begin  
                if (input_bit) begin  
                    next_state = S3;  
                    output_bit = 2'b10;  
                end else begin  
                    next_state = S0;  
                    output_bit = 2'b01;  
                end  
            end  
            S3: begin  
                if (input_bit) begin  
                    next_state = S2;  
                    output_bit = 2'b11;  
                end else begin  
                    next_state = S1;  
                    output_bit = 2'b00;  
                end  
            end  
            default: begin  
                next_state = S0;  
                output_bit = 2'b00;  
            end  
        endcase  
    end  
endmodule

