module spi_controller (
    input wire clk,
    input wire reset,
    input wire miso,
    input wire mosi,
    input wire start,
    output reg sclk,
    output reg [7:0] data_out,
    output reg data_ready
);
    reg [2:0] bit_count;
    reg [7:0] data_in;
    reg transmitting;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sclk <= 0;
            data_out <= 0;
            data_ready <= 0;
            bit_count <= 0;
            transmitting <= 0;
        end else begin
            if (start && !transmitting) begin
                transmitting <= 1;
                bit_count <= 0;
                data_in <= 0;
                data_ready <= 0;
            end

            if (transmitting) begin
                sclk <= ~sclk; // Toggle clock

                if (sclk) begin // On the rising edge of the clock
                    data_in <= {data_in[6:0], mosi}; // Shift in data
                    bit_count <= bit_count + 1;
                    if (bit_count == 7) begin
                        transmitting <= 0;
                        data_out <= {data_in[6:0], mosi};
                        data_ready <= 1; // Data is ready
                    end
                end
            end
        end
    end
endmodule

