module divide_by_8(  
    input clk,  
    input reset,  
    output reg out  
);  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 3'b000;  
            out <= 1'b0;  
        end else begin  
            if (count == 3'b111) begin  
                out <= ~out;  
                count <= 3'b000;  
            end else begin  
                count <= count + 1;  
            end  
        end  
    end  
endmodule

module des_round(
    input wire [31:0] data_in,
    input wire [47:0] key,
    output reg [31:0] data_out
);
    // Expansion: Expand 32-bit input to 48 bits
    wire [47:0] expanded_data;
    assign expanded_data = {data_in[31:24], data_in[31:24], data_in[23:16], data_in[23:16], data_in[15:8], data_in[15:8], data_in[7:0], data_in[7:0]};

    // Key Mixing: XOR expanded data with key
    wire [47:0] mixed_data;
    assign mixed_data = expanded_data ^ key;

    // Substitution: Stub for S-boxes (not implemented)
    wire [31:0] substituted_data;
    assign substituted_data = mixed_data[31:0]; // Placeholder for actual S-box implementation

    // Permutation: Stub for final permutation (not implemented)
    always @(*) begin
        data_out = substituted_data; // Placeholder for actual permutation implementation
    end
endmodule

