endmodule

module phase_detector (
    input wire clk1,
    input wire clk2,
    output reg lead,
    output reg lag,
    output reg in_phase
);

reg [1:0] state;

always @(posedge clk1 or posedge clk2) begin
    if (clk1 && !clk2) begin
        lead <= 1;
        lag <= 0;
        in_phase <= 0;
    end else if (!clk1 && clk2) begin
        lead <= 0;
        lag <= 1;
        in_phase <= 0;
    end else if (clk1 && clk2) begin
        lead <= 0;
        lag <= 0;
        in_phase <= 1;
    end else begin
        lead <= 0;
        lag <= 0;
        in_phase <= 0;
    end
end

endmodule

module vco (
    input wire clk,
    input wire rst,
    input wire [2:0] ctrl,
    output reg vco_out
);
    reg [2:0] count;
    reg [22:0] freq_counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            freq_counter <= 0;
            vco_out <= 0;
        end else begin
            if (freq_counter < (1 << (ctrl + 1))) begin
                freq_counter <= freq_counter + 1;
            end else begin
                vco_out <= ~vco_out;
                freq_counter <= 0;
            end
        end
    end
endmodule

