module pulse_generator(  
    input wire clk,  
    input wire rst,  
    input wire trigger,  
    input wire [3:0] width,  
    output reg pulse  
);  

    reg [3:0] count;  
    reg generating;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            pulse <= 0;  
            count <= 0;  
            generating <= 0;  
        end else begin  
            if (trigger && !generating) begin  
                generating <= 1;  
                count <= width;  
            end  
            if (generating) begin  
                pulse <= 1;  
                if (count > 0) begin  
                    count <= count - 1;  
                end else begin  
                    pulse <= 0;  
                    generating <= 0;  
                end  
            end  
        end  
    end  
endmodule

