module booth_multiplier #(parameter N = 8) (
    input clk,
    input rst,
    input signed [N-1:0] A,
    input signed [N-1:0] B,
    output reg signed [(2*N)-1:0] P
);
    reg signed [N-1:0] M;
    reg signed [N-1:0] Q;
    reg [N:0] count;
    reg Q_1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            P <= 0;
            M <= A;
            Q <= B;
            count <= 0;
            Q_1 <= 0;
        end else if (count < N) begin
            case ({Q[0], Q_1})
                2'b01: P <= P + M; // Add M to P
                2'b10: P <= P - M; // Subtract M from P
            endcase
            Q_1 <= Q[0];
            Q <= {P[(2*N)-1], Q[N-1:1]}; // Shift right
            P <= P >> 1; // Shift P right
            count <= count + 1;
        end
    end
endmodule

