module deserializer_32bit (  
    input wire clk,  
    input wire rst,  
    input wire [31:0] data_in,  
    input wire valid_in,  
    output reg [7:0] data_out,  
    output reg valid_out  
);  
    reg [2:0] count;  
    reg [31:0] shift_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            shift_reg <= 0;  
            data_out <= 0;  
            valid_out <= 0;  
        end else begin  
            if (valid_in) begin  
                shift_reg <= data_in;  
            end  
            if (count < 4) begin  
                data_out <= shift_reg[7:0];  
                shift_reg <= shift_reg >> 8;  
                count <= count + 1;  
                valid_out <= 1;  
            end else begin  
                valid_out <= 0;  
            end  
        end  
    end  
endmodule

